config.script:
// lembrete_rapido — agente `script` (MACRO), perfil `mensageiro`. Comportamento = ESTE arquivo (DADO).
//
// A cada rodada do cron (a cada 15 min), manda o LEMBRETE pelo WhatsApp para os agendamentos
// cujo horário de envio já chegou: `envio_em = max(início − antecedencia_minutos, hora_minima
// do dia da consulta)`. Ex.: consulta 15:30 → envio 13:30; consulta 08:30 → envio 08:00.
// Substitui o ponto `lembrete_rapido` do orquestrador (henriquessn1/fluxo-ideal#788).
//
// QUEM RECEBE: agendamento público, fora de status terminal, com paciente, que ainda não começou
// e cujo `envio_em` já passou. Confirmados e não confirmados recebem (paridade com o orquestrador).
// QUEM NÃO RECEBE (pula):
//   - marcado em cima da hora: criado DEPOIS do `envio_em` (já dentro da antecedência);
//   - atrasado: passou mais de `atraso_max_minutos` do `envio_em` (ex.: o agente ficou parado) —
//     melhor não mandar do que mandar "2h antes" a 20 min da consulta.
//
// ENVIO: 1 intenção por agendamento na mensageria (`enviar_intencao`), com chave de idempotência
// `lembrete_rapido:<agendamento_id>:<data_inicio>` — rodar de novo NÃO duplica (deduplicado);
// REAGENDAR muda o `data_inicio` e gera lembrete novo; CANCELAR antes do envio não envia.
//
// FALHA VISÍVEL (anti falso-verde): listar que falha NÃO vira "0 lembretes"; envio que volta
// não-2xx (ex.: 500 de template ausente) ou com status fora de aceito/deduplicado/agendado conta
// como FALHA, sai com log WARNING e `acao_bloqueada` no resumo — nunca como "enviado".
//
// O "agora" é a janela do cron (`event.window`), não o relógio do worker — a rodada é
// determinística mesmo se o worker atrasar (e testável).
//
// Injetados: event, config, context, call()->{ok,status_code,body}, log(), result().

var cfg = config || {};
function num(v, d) { return (v !== undefined && v !== null && !isNaN(Number(v))) ? Number(v) : d; }
var antecedenciaMin = num(cfg.antecedencia_minutos, 120);
var horaMinima = num(cfg.hora_minima, 8);
var atrasoMaxMin = num(cfg.atraso_max_minutos, 60);
var tzOffset = cfg.tz_offset || '-03:00';
var statusPular = cfg.status_pular || ['Cancelado', 'Falta', 'Finalizado'];
var perPage = Math.min(num(cfg.per_page, 100), 100); // a API aceita no máximo 100 por página
var template = cfg.template || 'lembrete_rapido';
var canal = cfg.canal || 'whatsapp';
var MAX_PAGINAS = 20;
var MIN_MS = 60000;

function unwrap(r) {
  if (!r || !r.ok) return null;
  var b = r.body;
  return (b && b.data !== undefined) ? b.data : b;
}
function offsetMin(s) {
  var m = /^([+-])(\d{2}):(\d{2})$/.exec(String(s));
  if (!m) return -180;
  var val = parseInt(m[2], 10) * 60 + parseInt(m[3], 10);
  return m[1] === '-' ? -val : val;
}
function pad(n) { return (n < 10 ? '0' : '') + n; }
// Data/hora LOCAL (fuso da clínica) de um instante absoluto.
function partesLocais(ms) {
  var d = new Date(ms + offsetMin(tzOffset) * MIN_MS);
  return {
    data: d.getUTCFullYear() + '-' + pad(d.getUTCMonth() + 1) + '-' + pad(d.getUTCDate()),
    hh: pad(d.getUTCHours()), mm: pad(d.getUTCMinutes())
  };
}
function isoLocal(ms) {
  var p = partesLocais(ms);
  var d = new Date(ms + offsetMin(tzOffset) * MIN_MS);
  return p.data + 'T' + p.hh + ':' + p.mm + ':' + pad(d.getUTCSeconds()) + tzOffset;
}

// --- enrich: 1º nome do paciente + apelido do profissional (com cache) ---
function primeiroNome(nome) {
  var s = String(nome || '').trim();
  if (!s) return null;
  var i = s.indexOf(' ');
  var p = i > 0 ? s.substring(0, i) : s;
  return p.charAt(0).toUpperCase() + p.substring(1).toLowerCase(); // "CELIRIA" -> "Celiria"
}
var _cliCache = {};
function clienteNome(id) {
  var k = String(id);
  if (_cliCache[k] !== undefined) return _cliCache[k];
  var d = unwrap(call('buscar_cliente', { cliente_id: k }));
  _cliCache[k] = (d && d.nome) ? primeiroNome(d.nome) : null;
  return _cliCache[k];
}
var _profCache = {};
function profApelido(id) {
  if (!id) return null;
  var k = String(id);
  if (_profCache[k] !== undefined) return _profCache[k];
  var d = unwrap(call('buscar_profissional', { id: k }));
  _profCache[k] = d ? (d.apelido || d.nome || null) : null;
  return _profCache[k];
}

// ---- "agora" = janela do cron ----
var nowMs = Date.parse((event && event.window) || '');
if (isNaN(nowMs)) nowMs = Date.now();

var pular = {};
for (var s = 0; s < statusPular.length; s++) pular[String(statusPular[s]).toLowerCase()] = true;

// Quem pode precisar do lembrete AGORA começa em (agora, agora + antecedência]:
// envio_em = max(início − antecedência, piso) <= agora  ⇒  início <= agora + antecedência.
var ini = isoLocal(nowMs);
var fim = isoLocal(nowMs + antecedenciaMin * MIN_MS);

var cont = { candidatos: 0, enviados: 0, deduplicados: 0, agendados: 0, aguardando: 0,
             pulado_em_cima: 0, pulado_atrasado: 0, sem_janela: 0, falhas: 0 };
var falhas = [];

// ---- 1) coleta paginada ----
var candidatos = [];
var pagina = 1;
while (pagina <= MAX_PAGINAS) {
  var raw = call('listar_janela', { data_inicio: ini, data_fim: fim, per_page: perPage, page: pagina });
  if (!raw || !raw.ok) {
    var http = (raw && raw.status_code) || null;
    var erro = (raw && raw.error) || 'chamada não-ok';
    log('lembrete_rapido: FALHA ao listar agendamentos (HTTP ' + (http || '?') + ' ' + erro + ')', 'warning');
    result({ acao_bloqueada: true, etapa: 'listar_janela', http: http, erro: erro, enviados: 0 });
    return { ok: false, erro: 'listar_falhou', http: http };
  }
  var lista = unwrap(raw);
  // Corpo fora do contrato (não é lista) NÃO é "0 agendamentos": falha visível.
  if (!Array.isArray(lista)) {
    log('lembrete_rapido: resposta da listagem fora do formato esperado (página ' + pagina + ')', 'warning');
    result({ acao_bloqueada: true, etapa: 'listar_janela', erro: 'formato_inesperado', enviados: 0 });
    return { ok: false, erro: 'listar_formato' };
  }
  if (!lista.length) break;
  for (var i = 0; i < lista.length; i++) {
    var ag = lista[i];
    if (!ag || !ag.id || !ag.cliente_id) continue;
    if (ag.visibilidade && String(ag.visibilidade) !== 'publica') continue;
    if (ag.status && pular[String(ag.status).toLowerCase()]) continue;
    var startMs = Date.parse(ag.data_inicio);
    if (isNaN(startMs) || startMs <= nowMs) continue;
    candidatos.push(ag);
  }
  if (lista.length < perPage) break;
  if (pagina === MAX_PAGINAS) {
    log('lembrete_rapido: listagem truncada em ' + MAX_PAGINAS + ' páginas — pode faltar lembrete', 'warning');
    cont.truncado = true;
  }
  pagina++;
}
cont.candidatos = candidatos.length;

// ---- 2) decide e envia (1 intenção por agendamento) ----
for (var c = 0; c < candidatos.length; c++) {
  var a = candidatos[c];
  var startMs2 = Date.parse(a.data_inicio);
  var loc = partesLocais(startMs2);
  var pisoMs = Date.parse(loc.data + 'T' + pad(horaMinima) + ':00:00' + tzOffset);
  var envioMs = Math.max(startMs2 - antecedenciaMin * MIN_MS, isNaN(pisoMs) ? 0 : pisoMs);

  if (envioMs >= startMs2) { cont.sem_janela++; continue; }   // consulta antes da hora mínima: nunca há horário de envio
  if (envioMs > nowMs) { cont.aguardando++; continue; }       // ainda não é hora
  if (nowMs - envioMs > atrasoMaxMin * MIN_MS) { cont.pulado_atrasado++; continue; }
  var criadoMs = Date.parse(a.created_at || '');
  if (!isNaN(criadoMs) && criadoMs > envioMs) { cont.pulado_em_cima++; continue; }

  var r = call('enviar_intencao', {
    destinatario_id: String(a.cliente_id),
    modo_entrega: 'force_channel',
    canal_solicitado: canal,
    template_slug: template,
    variaveis: {
      cliente_nome: clienteNome(a.cliente_id) || 'paciente',
      profissional_apelido: profApelido(a.profissional_id) || 'a clínica',
      hora: loc.hh + ':' + loc.mm
    },
    origem_ms: 'agentes',
    referencia_tipo: 'agendamento',
    referencia_id: String(a.id),
    // início normalizado em UTC: a chave não muda se o fuso da serialização mudar
    idempotency_key: 'lembrete_rapido:' + a.id + ':' + new Date(startMs2).toISOString()
  });
  var body = unwrap(r);
  var st = body && body.status;
  if (r && r.ok && st === 'aceito') cont.enviados++;
  else if (r && r.ok && st === 'deduplicado') cont.deduplicados++;
  else if (r && r.ok && st === 'agendado') cont.agendados++;
  else {
    cont.falhas++;
    var f = { agendamento_id: String(a.id), http: (r && r.status_code) || null,
              status: st || null, erro: (r && r.error) || null };
    falhas.push(f);
    log('lembrete_rapido: FALHA ao enviar (agendamento ' + f.agendamento_id + ', HTTP ' + (f.http || '?') +
        ', status ' + (f.status || '-') + ')', 'warning');
  }
}

log('lembrete_rapido: ' + cont.candidatos + ' candidato(s) — ' + cont.enviados + ' enviado(s), ' +
    cont.deduplicados + ' já enviado(s), ' + cont.agendados + ' agendado(s), ' + cont.falhas + ' falha(s)',
    cont.falhas ? 'warning' : 'info');
var resumo = cont;
resumo.janela = ini + '..' + fim;
if (falhas.length) { resumo.acao_bloqueada = true; resumo.etapa = 'enviar_intencao'; resumo.falhas_detalhe = falhas.slice(0, 20); }
result(resumo);
return { ok: falhas.length === 0, resumo: cont, janela: { de: ini, ate: fim } };
